import bpy,json
from pathlib import Path
out={}
for cn in ['Boat_Workshop','Pier_Working','Harbor_Arrival_Landing']:
 c=bpy.data.collections[cn];ts=0;bounds=[]
 for o in c.objects:
  if o.type!='MESH':continue
  o.data.calc_loop_triangles();ts+=len(o.data.loop_triangles)
  if o.name.startswith(('Closed lower','Side strake 00','Continuous','Walkboard_00','WaterPile_-1_0','LandingDeck')):
   bounds.append({'name':o.name,'lo':[min(v.co[i] for v in o.data.vertices) for i in range(3)],'hi':[max(v.co[i] for v in o.data.vertices) for i in range(3)],'location':list(o.location),'scale':list(o.scale)})
 out[cn]={'tris':ts,'bounds':bounds}
print(json.dumps(out))
